export class ValidationError extends Error { constructor(campo,mensagem){super(mensagem);this.name='ValidationError';this.campo=campo;} }
export class StorageError extends Error { constructor(mensagem,cause){super(mensagem,{cause});this.name='StorageError';} }
export async function criarTarefa(entrada, repositorio, criarId=()=>crypto.randomUUID()){ if(!entrada||typeof entrada.titulo!=='string'||!entrada.titulo.trim())throw new ValidationError('titulo','título obrigatório');const prazo=entrada.prazo;if(prazo!==undefined&&(!/^\d{4}-\d{2}-\d{2}$/.test(prazo)||Number.isNaN(Date.parse(prazo))||new Date(prazo).toISOString().slice(0,10)!==prazo))throw new ValidationError('prazo','prazo deve ser uma data ISO real');const tarefa={id:criarId(),titulo:entrada.titulo.trim(),...(prazo?{prazo}:{}),status:'a-fazer'};try{await repositorio.salvar(structuredClone(tarefa));}catch(cause){throw new StorageError('não foi possível salvar a tarefa',cause);}return tarefa; }

export function criarCadastroCliente(repo,nome,email,idade){const dados=validar(nome,email,idade);if(!dados.ok)return dados;const clientes=repo.listar();if(clientes.some(c=>c.email===dados.value.email))return{ok:false,erro:'email já cadastrado'};const cliente={id:clientes.length+1,...dados.value};repo.salvar(cliente);repo.registrar('cadastro',cliente.email);return{ok:true,cliente};}
export function atualizarCliente(repo,id,nome,email,idade){const dados=validar(nome,email,idade);if(!dados.ok)return dados;const clientes=repo.listar();const atual=clientes.find(c=>c.id===id);if(!atual)return{ok:false,erro:'cliente não encontrado'};const cliente={id,...dados.value};repo.atualizar(cliente);repo.registrar('atualização',id);return{ok:true};}
export function validar(nome,email,idade){if(nome==null||String(nome).trim()==='')return{ok:false,erro:'nome obrigatório'};if(email==null||!String(email).includes('@'))return{ok:false,erro:'email inválido'};if(idade==null||!Number.isFinite(Number(idade))||Number(idade)<18)return{ok:false,erro:'idade mínima 18'};return{ok:true,value:{nome:String(nome).trim(),email:String(email).trim().toLowerCase(),idade:Number(idade)}};}
